mapper.select:
SELECT COUNT(*)
FROM reservations
WHERE room_id = #{roomId}
  AND status IN ('PENDING', 'CONFIRMED')
  AND check_in < #{checkOut}
  AND check_out > #{checkIn}

SELECT id AS id, hotel_id AS hotelId, status AS status, check_out AS checkOut
FROM reservations
WHERE id = #{reservationId} AND user_id = #{userId}

SELECT COUNT(*)
FROM reservations
WHERE user_id = #{userId}
  AND status IN ('PENDING', 'CONFIRMED')
  AND check_out >= #{today}

SELECT COUNT(*)
FROM reservations
WHERE user_id = #{userId}
  AND status = 'CONFIRMED'
  AND check_out < #{today}
